create or replace TABLE KFL_PRODUCTION.DBP_DATA.INVENTUR_BEWERTUNG (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH',
	INVENTURART_ID NUMBER(38,0) NOT NULL COMMENT 'Inventurart (international nicht identisch)',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
	DAT_PREIS DATE NOT NULL COMMENT 'Datum der Inventurbewertung. Das Preisdatum wird benötigt, um die Inventur mit dem zu diesem Zeitpunkt gültigen Preis zu bewerten. Inventurdifferenzen können mehrmals im Jahr bewertet werden.',
	BELEG_ERFASSER_ID VARCHAR(20) NOT NULL COMMENT 'ID des Beleg-Erfassers. Kann Batch-Usernamen oder FB enthalten. Aus Datenschutzgründen darf in den Bewegungsdaten nur der Fachbereich des Erfassers abgebildet werden.',
	DAT_ERSTELLUNG DATE NOT NULL COMMENT 'Erstelldatum des Datensatzes im Quellsystem.',
	ZEIT_INVENTUR TIME(0) NOT NULL COMMENT 'Uhrzeit der Inventur.',
	WG_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Warengruppe',
	OWG_ID NUMBER(38,0) NOT NULL COMMENT 'ID der Oberwarengruppe',
	ARTHIERTYP_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel-Hierarchie-Typ-ID: kennzeichnet, ob es sich um eine Hierarchie mit zwei- oder dreistelligen Warengruppen handelt.',
	MWST_ID NUMBER(38,0) NOT NULL COMMENT 'Mehrwertsteuersatz-ID (<> Mehrwertsteuersatz!)',
	RATE_STEUERSATZ NUMBER(38,2) NOT NULL COMMENT 'Rate des Mehrwertsteuersatzes.',
	INVENTUR_TYP_TXT VARCHAR(50) NOT NULL COMMENT 'Freitext zur Möglichkeit einer detaillierteren Kategorisierung der Inventurarten.',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.B. CZK, EUR',
	MENGE_BME_INVENTUR_DIFF NUMBER(38,3) NOT NULL COMMENT 'Gesamtmenge der ermittelten und verdichteten Inventurdifferenz in Basismengeneinheit auf Ebende Filiale und Artikel.',
	MENGE_BME_INVENTUR_DIEBSTAHL NUMBER(38,3) NOT NULL COMMENT 'Menge der durch Diebstahl verursachten Inventurdifferenz in Basismengeneinheit auf Ebene Filiale und Artikel.',
	PREIS_VK_BRUTTO NUMBER(38,4) NOT NULL COMMENT 'Brutto-Verkaufspreis des Artikels zum Zeitpunkt des Preisdatums.',
	PREIS_VK_NETTO NUMBER(38,4) NOT NULL COMMENT 'Netto-Verkaufspreis des Artikels zum Zeitpunkt des Preisdatums.',
	PREIS_VK_BRUTTO_KORRIGIERT NUMBER(38,4) NOT NULL COMMENT 'Korrigierter Brutto-Verkaufspreis des Artikels. Es kann vorkommen, dass dem betrag_vk_brutto Fehler unterliegen. In diesen Fällen kann vom Fachbereich ein korrigierter Betrag angegeben werden. Tritt dieser Fall ein, ist die manuell korrigierte Eingabe führend.',
	BETRAG_VK_NETTO_INVENTUR_DIFF NUMBER(38,4) NOT NULL COMMENT 'Mit dem Netto-Verkaufspreis bewertete Inventurdifferenz: menge_inventur_diff * betrag_vk_netto',
	BETRAG_VK_NETTO_INVENTUR_DIEBSTAHL NUMBER(38,4) NOT NULL COMMENT 'Mit dem Netto Verkaufspreis bewertete durch Diebstahl verursachte Inventurdifferenz: menge_inventur_diebstahl * betrag_vk_netto.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_INVENTUR_BEWERTUNG primary key (MANDANT_ID, INVENTURART_ID, WUP_ID, NB_ID, ART_ID, DAT_PREIS)
)COMMENT='Tabelle enthält bewertete Inventurdaten auf Ebene Artikel - Filiale. Dazu werden die Positionen in den Materialbelegen auf diese Ebene verdichtet. Dies ist notwendig um verschiedene Besonderheiten abzubilden (bspw. Umzüge, Filialumgliederung, Kleingebindeaufschlag, Treueartikel). Aktuelle Quelltabelle in SAP: ZWWX_INVWERT.'
;